/**
 * Copies the season catalog generated by scripts/build-cards into the app bundle,
 * so cards render instantly and offline. Run after each pipeline build.
 */
import { copyFileSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const source = join(here, '..', '..', 'data', 'cards.season1.json');
const target = join(here, '..', 'src', 'data', 'cards.season1.json');

const catalog = JSON.parse(readFileSync(source, 'utf8')) as { cards?: unknown[] };
if (!Array.isArray(catalog.cards) || catalog.cards.length === 0) {
  console.error(`No cards found in ${source}`);
  process.exit(1);
}
copyFileSync(source, target);
console.log(`Synced ${catalog.cards.length} cards to ${target}`);
